 "content": "def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # Draw a horizontal spine through the pair of markers sharing a row,
    # then extend each other marker vertically toward that spine.
    rows={r for r,c in pts}
    spine=next((r for r in rows if sum(rr==r for rr,cc in pts)==2), None)
    if spine is None: return out
    cols=[c for r,c in pts if r==spine]
    for c in range(min(cols),max(cols)+1):
        if out[spine][c]==0: out[spine][c]=3
    for r,c in pts:
        if r==spine: continue
        for rr in range(min(r,spine)+1,max(r,spine)):
            if out[rr][c]==0: out[rr][c]=3
    return out
